import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';

import { Training } from '../../../domain';
import { Empty } from '../../Empty';
import {
  StyledCard,
  StyledCardContent,
  StyledCardImage,
  StyledCardTag,
  StyledCardTitle,
  StyledContentWrapper,
  StyledLink,
  StyledTagContainer,
} from './TrainingCard.styles';

interface TrainingCardProps {
  training: Training;
  pillarId?: string | null;
  fromRecentlyAdded?: boolean;
}

export const TrainingCard = ({
  training,
  pillarId = null,
  fromRecentlyAdded = false,
}: TrainingCardProps) => {
  const navigate = useNavigate();

  const handleOpenTraining = useCallback(
    (training: Training) => {
      if (pillarId) {
        navigate(`/training-hub/${pillarId}/training/${training.id}`);
      } else {
        navigate(`/training-hub/training/${training.id}`, {
          state: fromRecentlyAdded ? { from: 'recently-added' } : undefined,
        });
      }
    },
    [navigate, pillarId, fromRecentlyAdded],
  );

  return (
    <StyledCard onClick={() => handleOpenTraining(training)}>
      {!training ? (
        <Empty type="no-data" description="Training Couldn't Load" />
      ) : (
        <>
          <StyledCardImage src={training.image} alt="Training Card" />
          <StyledContentWrapper>
            <StyledCardContent>
              <StyledCardTitle>{training.title}</StyledCardTitle>
              <StyledTagContainer>
                {training?.tags?.map((tag: string) => (
                  <StyledCardTag title={tag} key={tag}>
                    {tag}
                  </StyledCardTag>
                ))}
              </StyledTagContainer>
            </StyledCardContent>
            <StyledLink>Open Training</StyledLink>
          </StyledContentWrapper>
        </>
      )}
    </StyledCard>
  );
};
